window.PULSECARE_CONDITIONS = [{"name": "High blood pressure", "cat": "Heart health", "summary": "Blood pressure is the force of your blood pushing against the walls of your arteries. Each time your heart beats, it pumps blood into the arteries. Your blood pressure is highest when your heart beats, pumping the blood. This is called systolic pressure. When your heart is at rest, between beats, your blood pressure falls.…", "sourceUrl": "https://medlineplus.gov/highbloodpressure.html", "id": "high-blood-pressure"}, {"name": "Asthma", "cat": "Breathing", "summary": "Asthma is a chronic (long-term) lung disease. It affects your airways, the tubes that carry air in and out of your lungs. When you have asthma, your airways can become inflamed and narrowed. This can cause wheezing, coughing, and tightness in your chest. When these symptoms get worse than usual, it is called an asthma attack…", "sourceUrl": "https://medlineplus.gov/asthma.html", "id": "asthma"}, {"name": "Type 2 diabetes", "cat": "Metabolic health", "summary": "Type 2 diabetes is a disease in which your blood glucose, or blood sugar, levels are too high. Glucose is your main source of energy. It comes from the foods you eat. A hormone called insulin helps the glucose get into your cells to give them energy. If you have diabetes, your body doesn't make enough insulin or doesn't use…", "sourceUrl": "https://medlineplus.gov/diabetestype2.html", "id": "type-2-diabetes"}, {"name": "High cholesterol", "cat": "Heart health", "summary": "Cholesterol is a waxy, fat-like substance that's found in all the cells in your body. Your body needs some cholesterol to make hormones, vitamin D, and substances that help you digest foods. Your body makes all the cholesterol it needs. Cholesterol is also found in foods from animal sources, such as egg yolks, meat, and cheese.", "sourceUrl": "https://medlineplus.gov/cholesterol.html", "id": "high-cholesterol"}, {"name": "Coronary artery disease", "cat": "Heart health", "summary": "Coronary artery disease (CAD) is the most common type of heart disease in the United States and a leading cause of death for both men and women.", "sourceUrl": "https://medlineplus.gov/coronaryarterydisease.html", "id": "coronary-artery-disease"}, {"name": "Heart failure", "cat": "Heart health", "summary": "Heart failure means that your heart can't pump enough oxygen-rich blood to meet your body's needs. Heart failure doesn't mean that your heart has stopped or is about to stop beating. But without enough blood flow, your organs may not work well, which can cause serious problems.", "sourceUrl": "https://medlineplus.gov/heartfailure.html", "id": "heart-failure"}, {"name": "Atrial fibrillation", "cat": "Heart health", "summary": "Atrial fibrillation, also known as AFib or AF, is one of the most common types of arrhythmias. Arrhythmias are problems with the rate or rhythm of your heartbeat. They can cause your heart to beat too slowly, too fast, or in an irregular way.", "sourceUrl": "https://medlineplus.gov/atrialfibrillation.html", "id": "atrial-fibrillation"}, {"name": "Stroke", "cat": "Brain & nerves", "summary": "A stroke happens when there is a loss of blood flow to part of the brain. Your brain cells cannot get the oxygen and nutrients they need from blood, and they start to die within a few minutes. This can cause lasting brain damage, long-term disability, or even death.", "sourceUrl": "https://medlineplus.gov/stroke.html", "id": "stroke"}, {"name": "Obesity", "cat": "Metabolic health", "summary": "Obesity is a disease that means having too much body fat. It is different from being overweight, which means weighing too much. Both terms mean that your weight is greater than what's considered healthy for your height.", "sourceUrl": "https://medlineplus.gov/obesity.html", "id": "obesity"}, {"name": "Prediabetes", "cat": "Metabolic health", "summary": "Prediabetes means that your blood glucose, or blood sugar, levels are higher than normal but not high enough to be called diabetes. Glucose comes from the foods you eat. Too much glucose in your blood can damage your body over time.", "sourceUrl": "https://medlineplus.gov/prediabetes.html", "id": "prediabetes"}, {"name": "Hypothyroidism", "cat": "Metabolic health", "summary": "Hypothyroidism, or underactive thyroid, happens when your thyroid gland doesn't make enough thyroid hormones to meet your body's needs.", "sourceUrl": "https://medlineplus.gov/hypothyroidism.html", "id": "hypothyroidism"}, {"name": "Hyperthyroidism", "cat": "Metabolic health", "summary": "Hyperthyroidism, or overactive thyroid, happens when your thyroid gland makes more thyroid hormones than your body needs.", "sourceUrl": "https://medlineplus.gov/hyperthyroidism.html", "id": "hyperthyroidism"}, {"name": "Chronic kidney disease", "cat": "Kidney & urinary health", "summary": "You have two kidneys, each about the size of your fist. Their main job is to filter your blood. They remove wastes and extra water, which become urine. They also keep the body's chemicals balanced, help control blood pressure, and make hormones.", "sourceUrl": "https://medlineplus.gov/chronickidneydisease.html", "id": "chronic-kidney-disease"}, {"name": "Steatotic (fatty) liver disease", "cat": "Digestive health", "summary": "Your liver is the largest organ inside your body. It helps you digest food, store energy, and remove harmful substances (toxins). Steatotic liver disease, formerly called fatty liver disease, happens when too much fat builds up in your liver. It's typical to have some fat in your liver cells, but too much can be a problem.", "sourceUrl": "https://medlineplus.gov/steatoticliverdisease.html", "id": "fatty-liver-disease"}, {"name": "Acid reflux (GERD)", "cat": "Digestive health", "summary": "Sometimes, after eating a large meal or lying down too soon after eating, you might feel acid coming up into your throat. This is called gastroesophageal reflux (GER). It happens when the muscle at the end of your esophagus (the tube that carries food from your mouth to your stomach) doesn't close properly. Stomach contents…", "sourceUrl": "https://medlineplus.gov/gerd.html", "id": "gerd"}, {"name": "Irritable bowel syndrome (IBS)", "cat": "Digestive health", "summary": "Irritable bowel syndrome (IBS) is a problem that affects the large intestine. It can cause abdominal cramping, bloating, and a change in bowel habits. Some people with the disorder have constipation. Some have diarrhea. Others go back and forth between the two. Although IBS can cause a great deal of discomfort, it does not…", "sourceUrl": "https://medlineplus.gov/irritablebowelsyndrome.html", "id": "irritable-bowel-syndrome"}, {"name": "Constipation", "cat": "Digestive health", "summary": "Constipation means having fewer than three bowel movements a week. The stool (poop) can be hard and dry. Sometimes it is painful to pass. At one time or another, almost everyone gets constipated. In most cases, it lasts a short time and is not serious.", "sourceUrl": "https://medlineplus.gov/constipation.html", "id": "constipation"}, {"name": "Hemorrhoids", "cat": "Digestive health", "summary": "Hemorrhoids are swollen, inflamed veins around your anus or the lower part of your rectum. There are two types:", "sourceUrl": "https://medlineplus.gov/hemorrhoids.html", "id": "hemorrhoids"}, {"name": "Osteoarthritis", "cat": "Joints & muscles", "summary": "Osteoarthritis, sometimes called OA, is a type of arthritis that only affects the joints, usually in the hands, knees, hips, neck, and lower back. It's the most common type of arthritis.", "sourceUrl": "https://medlineplus.gov/osteoarthritis.html", "id": "osteoarthritis"}, {"name": "Rheumatoid arthritis", "cat": "Joints & muscles", "summary": "Rheumatoid arthritis (RA) is a form of arthritis that causes pain, swelling, and stiffness in your joints. RA is an autoimmune disease. Although it is most common in the wrist and fingers, this disease can cause your immune system to attack any joint tissue. The inflammation (swelling) that comes with RA can also affect…", "sourceUrl": "https://medlineplus.gov/rheumatoidarthritis.html", "id": "rheumatoid-arthritis"}, {"name": "Osteoporosis", "cat": "Joints & muscles", "summary": "Osteoporosis is a disease in which your bones become weak and are likely to fracture (break). The disease can develop when your bone mineral density and bone mass decrease. It can also happen if the structure and strength of your bones change.", "sourceUrl": "https://medlineplus.gov/osteoporosis.html", "id": "osteoporosis"}, {"name": "Back pain", "cat": "Joints & muscles", "summary": "If you've ever groaned, \"Oh, my aching back!\", you are not alone. Back pain is one of the most common medical problems, affecting 8 out of 10 people at some point during their lives. Back pain can range from a dull, constant ache to a sudden, sharp pain. Acute back pain comes on suddenly and usually lasts from a few days to…", "sourceUrl": "https://medlineplus.gov/backpain.html", "id": "back-pain"}, {"name": "Gout", "cat": "Joints & muscles", "summary": "Gout is a common type of inflammatory arthritis. It causes pain, swelling, and redness in one or more joints. It usually happens as a flare, which can last for a week or two and then gets better. The flares often begin in your big toe or a lower limb.", "sourceUrl": "https://medlineplus.gov/gout.html", "id": "gout"}, {"name": "Fibromyalgia", "cat": "Joints & muscles", "summary": "Fibromyalgia is chronic (long-lasting) condition that causes pain all over the body, fatigue, and other symptoms. There is no cure, but treatments can help with the symptoms.", "sourceUrl": "https://medlineplus.gov/fibromyalgia.html", "id": "fibromyalgia"}, {"name": "Migraine", "cat": "Brain & nerves", "summary": "Migraines are a recurring type of headache. They cause moderate to severe pain that is throbbing or pulsing. The pain is often on one side of your head. You may also have other symptoms, such as nausea and weakness. You may be sensitive to light and sound.", "sourceUrl": "https://medlineplus.gov/migraine.html", "id": "migraine"}, {"name": "Headache (including tension headaches)", "cat": "Brain & nerves", "summary": "Almost everyone has had a headache. Headache is the most common form of pain. It's a major reason people miss days at work or school or visit the doctor.", "sourceUrl": "https://medlineplus.gov/headache.html", "id": "headache"}, {"name": "Depression", "cat": "Mental health", "summary": "Depression is more than a feeling of being sad or irritable for a few days. It's a serious mood disorder. As one of the most common mental disorders in the United States, depression can affect how you think, feel, and your everyday life. You may not know why you feel this way, but even basic daily activities such as…", "sourceUrl": "https://medlineplus.gov/depression.html", "id": "depression"}, {"name": "Anxiety disorders", "cat": "Mental health", "summary": "Anxiety is a feeling of fear, dread, and uneasiness. It might cause you to sweat, feel restless and tense, and have a rapid heartbeat. It can be a normal reaction to stress. For example, you might feel anxious when faced with a difficult problem at work, before taking a test, or before making an important decision. It can…", "sourceUrl": "https://medlineplus.gov/anxiety.html", "id": "anxiety"}, {"name": "Insomnia", "cat": "Sleep health", "summary": "Insomnia is a common sleep disorder. If you have it, you may have trouble falling asleep, staying asleep, or both. As a result, you may get too little sleep or have poor-quality sleep. You may not feel refreshed when you wake up.", "sourceUrl": "https://medlineplus.gov/insomnia.html", "id": "insomnia"}, {"name": "Sleep apnea", "cat": "Sleep health", "summary": "Sleep apnea is a common disorder that causes your breathing to stop or get very shallow. Breathing pauses can last from a few seconds to minutes. They may occur 30 times or more an hour.", "sourceUrl": "https://medlineplus.gov/sleepapnea.html", "id": "sleep-apnea"}, {"name": "Attention-deficit/hyperactivity disorder (ADHD)", "cat": "Mental health", "summary": "ADHD is a neurodevelopmental disorder. It is usually first diagnosed in childhood and often lasts into adulthood. But some people don't get diagnosed with ADHD until they are adults. ADHD involves:", "sourceUrl": "https://medlineplus.gov/attentiondeficithyperactivitydisorder.html", "id": "adhd"}, {"name": "Allergies (including seasonal allergies)", "cat": "Allergies & breathing", "summary": "An allergy is a reaction by your immune system to something that does not bother most other people. People who have allergies often are sensitive to more than one thing. Substances that often cause reactions are:", "sourceUrl": "https://medlineplus.gov/allergy.html", "id": "seasonal-allergies"}, {"name": "Sinusitis", "cat": "Allergies & breathing", "summary": "Sinusitis means your sinuses are inflamed. The cause can be an infection or another problem. Your sinuses are hollow air spaces within the bones surrounding the nose. They produce mucus, which drains into the nose. If your nose is swollen, this can block the sinuses and cause pain.", "sourceUrl": "https://medlineplus.gov/sinusitis.html", "id": "sinusitis"}, {"name": "Chronic obstructive pulmonary disease (COPD)", "cat": "Breathing", "summary": "COPD (chronic obstructive pulmonary disease) is a group of lung diseases that make it hard to breathe and get worse over time.", "sourceUrl": "https://medlineplus.gov/copd.html", "id": "copd"}, {"name": "Common cold", "cat": "Infections", "summary": "The common cold is a mild infection of your upper respiratory tract (which includes your nose and throat). Colds are probably the most common illness. Adults have an average of 2-3 colds per year, and children have even more. Colds are more common in the winter and spring, but you can get them at any time.", "sourceUrl": "https://medlineplus.gov/commoncold.html", "id": "common-cold"}, {"name": "Influenza (flu)", "cat": "Infections", "summary": "The flu, also called influenza, is a respiratory infection caused by viruses. Each year, millions of Americans get sick with the flu. Sometimes it causes mild illness. But it can also be serious or even deadly, especially for people over 65, newborn babies, and people with certain chronic illnesses.", "sourceUrl": "https://medlineplus.gov/flu.html", "id": "influenza"}, {"name": "COVID-19", "cat": "Infections", "summary": "COVID-19 (coronavirus disease 2019) is an illness caused by a virus. This virus is a coronavirus called SARS-CoV-2. It spreads when a person who has the infection breathes out droplets and very small particles that contain the virus. On this page, you'll find links to resources on important issues such as symptoms, risks,…", "sourceUrl": "https://medlineplus.gov/covid19coronavirusdisease2019.html", "id": "covid-19"}, {"name": "Pneumonia", "cat": "Infections", "summary": "Pneumonia is an infection in one or both of the lungs. It causes the air sacs of the lungs to fill up with fluid or pus. It can range from mild to severe, depending on the type of germ causing the infection, your age, and your overall health.", "sourceUrl": "https://medlineplus.gov/pneumonia.html", "id": "pneumonia"}, {"name": "Urinary tract infection (UTI)", "cat": "Kidney & urinary health", "summary": "The urinary system is the body's drainage system for removing wastes and extra water. It includes two kidneys, two ureters, a bladder, and a urethra. Urinary tract infections (UTIs) are the second most common type of infection in the body.", "sourceUrl": "https://medlineplus.gov/urinarytractinfections.html", "id": "urinary-tract-infection"}, {"name": "Urinary incontinence", "cat": "Kidney & urinary health", "summary": "Urinary incontinence (UI) is the loss of bladder control, or being unable to control urination. It is a common condition. It can range from being a minor problem to something that greatly affects your daily life. In any case, it can get better with proper treatment.", "sourceUrl": "https://medlineplus.gov/urinaryincontinence.html", "id": "urinary-incontinence"}, {"name": "Enlarged prostate (BPH)", "cat": "Kidney & urinary health", "summary": "The prostate is a gland in the male reproductive system. It lies just below the bladder. It makes fluid that is part of semen.", "sourceUrl": "https://medlineplus.gov/enlargedprostatebph.html", "id": "enlarged-prostate"}, {"name": "Acne", "cat": "Skin health", "summary": "Acne is a common skin disease that causes pimples. Pimples form when hair follicles under your skin clog up. Most pimples form on the face, neck, back, chest, and shoulders. Anyone can get acne, but it is common in teenagers and young adults. It is not serious, but it can cause scars.", "sourceUrl": "https://medlineplus.gov/acne.html", "id": "acne"}, {"name": "Eczema", "cat": "Skin health", "summary": "Eczema is a term for several different types of skin swelling. Eczema is also called dermatitis. Most types cause dry, itchy skin and rashes on the face, inside the elbows and behind the knees, and on the hands and feet. Scratching the skin can cause it to turn red, and to swell and itch even more.", "sourceUrl": "https://medlineplus.gov/eczema.html", "id": "eczema"}, {"name": "Psoriasis", "cat": "Skin health", "summary": "Psoriasis is a skin disease that causes itchy or sore patches of thick, red skin with silvery scales. You usually get the patches on your elbows, knees, scalp, back, face, palms and feet, but they can show up on other parts of your body. Some people who have psoriasis also get a form of arthritis called psoriatic arthritis.", "sourceUrl": "https://medlineplus.gov/psoriasis.html", "id": "psoriasis"}, {"name": "Cataracts", "cat": "Vision & hearing", "summary": "A cataract is a clouding of the clear lens inside your eye. This cloudiness blocks light from reaching the back of the eye, making it harder to see clearly. A cataract can affect one or both eyes, but it doesn't spread from one eye to the other.", "sourceUrl": "https://medlineplus.gov/cataract.html", "id": "cataracts"}, {"name": "Hearing loss", "cat": "Vision & hearing", "summary": "It's frustrating to be unable to hear well enough to enjoy talking with friends or family. Hearing disorders make it hard, but not impossible, to hear. They can often be helped. Deafness can keep you from hearing sound at all.", "sourceUrl": "https://medlineplus.gov/hearingdisordersanddeafness.html", "id": "hearing-loss"}, {"name": "Anemia", "cat": "Blood health", "summary": "If you have anemia, your blood does not carry enough oxygen to the rest of your body. The most common cause of anemia is not having enough iron. Your body needs iron to make hemoglobin. Hemoglobin is an iron-rich protein that gives the red color to blood. It carries oxygen from the lungs to the rest of the body.", "sourceUrl": "https://medlineplus.gov/anemia.html", "id": "anemia"}, {"name": "Breast cancer", "cat": "Cancer", "summary": "Breast cancer is a cancer that starts in breast tissue. It happens when cells in the breast change and grow out of control. New cells grow even when you don't need them, and old cells don't die when they should. These extra cells can form a mass called a tumor.", "sourceUrl": "https://medlineplus.gov/breastcancer.html", "id": "breast-cancer"}, {"name": "Prostate cancer", "cat": "Cancer", "summary": "Cancer is a disease in which cells in the body grow out of control. Prostate cancer begins in the cells of the prostate. The prostate is a gland in the male reproductive system. It lies just below the bladder. It makes fluid that is part of semen.", "sourceUrl": "https://medlineplus.gov/prostatecancer.html", "id": "prostate-cancer"}, {"name": "Alzheimer's disease", "cat": "Brain & nerves", "summary": "Alzheimer's disease (AD) is the most common form of dementia among older people. Dementia is a brain disorder that seriously affects thinking and memory skills. If you have AD, it can impair your ability to reason or learn new skills until it becomes difficult to complete daily activities.", "sourceUrl": "https://medlineplus.gov/alzheimersdisease.html", "id": "alzheimers-disease"}];
